"""Matched single serial full workflows; no stable statistical speed claim."""
import json,sys,re,shlex
from pathlib import Path
R=Path.cwd();sys.path.insert(0,str(R/'tools'))
from pre_route_endpoints import sha
seed=R/'experiments/aes_native_demand_full_workflow_v1_2026-10-08';cold=R/'experiments/aes_native_demand_cold_full_workflow_v1_2026-10-08';bindings={str(Path(__file__)):sha(Path(__file__))};datasets=[]
for root,key in [(seed,'fresh_estimates_native_full_endpoints_capacity_canonical_pass'),(cold,'fresh_cold_full_endpoints_capacity_canonical_pass')]:
 proof=root/'verification.json';p=json.loads(proof.read_text());assert p[key] and all(sha(k)==v for k,v in p['bindings'].items());receipt=root/'receipt.json';d=json.loads(receipt.read_text());assert all(sha(k)==v for k,v in d['bindings'].items());bindings.update({str(proof):sha(proof),str(receipt):sha(receipt)});datasets.append(d['rows'])
assert [r['name'] for r in datasets[0]]==[r['name'] for r in datasets[1]]==['aes_cipher','aes_inv_cipher'];rows=[]
for s,c in zip(*datasets):
 name=s['name'];assert s['canonical']['semantic_consistency_gate_pass'] and c['canonical']['semantic_consistency_gate_pass'];logged_commands=[shlex.split(re.search(r'VPR was run with the following command-line:\n([^\n]+)',(root/name/'native.log').read_text())[1]) for root in [seed,cold]];assert logged_commands[0]==logged_commands[1];assert s['all_original_queries']==c['all_original_queries'] and s['native_ignored_queries']==c['native_ignored_queries'];assert s['required_connections']==c['required_connections']
 for root,r in [(seed,s),(cold,c)]:assert all(sha(k)==v for k,v in r['files'].items()) and all(sha(k)==v for k,v in r['canonical']['files'].items())
 for file in ['design.blif','design.net','design.place','scope_partition.json','identity.jsonl']:assert sha(seed/name/file)==sha(cold/name/file)
 a=json.loads((seed/name/'endpoints.json').read_text());b=json.loads((cold/name/'endpoints.json').read_text());assert a['connections']==b['connections'] and a['graph_sha256']==b['graph_sha256']
 logs=[(seed/name/'native.log').read_text(),(cold/name/'native.log').read_text()];assert 'NET-aware seed imported' in logs[0] and 'NET-aware seed imported' not in logs[1];iterations=[int(re.search(r'Successfully routed after (\d+) routing iterations',text)[1]) for text in logs]
 quality=s['cpd_ns']<=c['cpd_ns'] and s['wirelength']<=c['wirelength'];time_gain=s['actual_complete_workflow_seconds']<c['actual_complete_workflow_seconds'];rows.append({'name':name,'physical_connections':s['required_connections'],'ignored_connections_accounted':s['native_ignored_queries'],'seed_cpd_ns':s['cpd_ns'],'cold_cpd_ns':c['cpd_ns'],'seed_wirelength':s['wirelength'],'cold_wirelength':c['wirelength'],'seed_iterations':iterations[0],'cold_iterations':iterations[1],'seed_complete_seconds':s['actual_complete_workflow_seconds'],'cold_complete_seconds':c['actual_complete_workflow_seconds'],'extra_complete_seconds':s['actual_complete_workflow_seconds']-c['actual_complete_workflow_seconds'],'seed_stage_seconds':s['stages'],'cold_stage_seconds':c['stages'],'quality_gate_pass':quality,'observed_full_time_gain':time_gain,'joint_quality_and_observed_time_gate_pass':quality and time_gain})
assert all(sha(k)==v for k,v in bindings.items());out=R/'experiments/aes_native_demand_full_cold_comparison_v1_2026-10-08';out.mkdir();(out/'comparison.json').write_text(json.dumps({'bindings':bindings,'rows':rows,'scope':'Both complete fixed-input conversion/identity partition/native/audit/semantic canonical workflows freshly timed. Seed additionally charges floors/two feedback/selection/serialization. Compilation and upstream pack/place/RR generation excluded for both. Single serial noninterleaved runs; no stable statistical speed claim. Previously observed AES-derived mapped family, original HDL relation and heldout validation remain unproven. Original zero-counter gates retained false.'},indent=2)+'\n');print(json.dumps(rows,indent=2))
